// T116 D7 / P7: the host's input into the Next's: the C64 key matrix (keys[col * 8 + row], 1 = down) into the Next's 8x5 matrix, read by the
// address lines the machine puts out (o_KBD_ROW: A15:A8, a zero selects a half-row) and into the 16 extended keys; both joystick ports into the
// 12 bit joystick words of the MD pad connector; the app's mouse counters into the Kempston mouse. The 8x5 matrix is the Spectrum's, so it
// is the table of the ZX core (zx_keys.v, generated by tools/zxcpc_keys.py: SHIFT alone is CAPS SHIFT, the cursor keys, DEL, the punctuation
// are the Spectrum's CAPS/SYMBOL combinations); the keys the Next has beyond the Spectrum are the extended keys (membrane.vhd: two more
// columns on every half-row, bit 2 * row + 1 is column 6, bit 2 * row column 5):
//   bit  0 EXTEND   1 UP      2 CAPS LOCK  3 GRAPH   4 TRUE VIDEO  5 INV VIDEO  6 BREAK  7 EDIT   8 ;  9 "  10 ,  11 .  12 DELETE  13 RIGHT  14 LEFT  15 DOWN
// and the C64 keys that make them (this project's choice, listed in the report): EXTEND = C=, UP = SHIFT + CRSR down, DOWN = CRSR down,
// LEFT = SHIFT + CRSR right, RIGHT = CRSR right, DELETE = DEL, EDIT = HOME, BREAK = RUN/STOP, CAPS LOCK = CTRL, GRAPH = <-, TRUE VIDEO = F1,
// INV VIDEO = F3, ; = ;, " = SHIFT + 2, , = , and . = .  (the membrane also enters each of them as a CAPS/SYMBOL combination in the 8x5 matrix, which
// the ZX table already does for the C64 key of the same name; o_KBD_CANCEL is not honoured, section 4 of the build notes).
// Joystick words (md6_joystick_connector_x2.vhd): bit 0 R, 1 L, 2 D, 3 U, 4 B (the fire button of an Atari stick), 5 C, 6 A, 7 START, 8 Y, 9 Z, 10 X, 11 MODE.
// Written for this project (TREX), no upstream code.
`timescale 1ns / 1ps
module zxn_keys (
    input  wire [63:0] keys,
    input  wire [7:0]  row,              // o_KBD_ROW
    output wire [4:0]  col,              // i_KBD_COL, 0 = pressed
    output wire [15:0] ext,              // i_KBD_EXTENDED_KEYS, 1 = pressed
    input  wire [4:0]  joy1,             // up, down, left, right, fire (active high)
    input  wire [4:0]  joy2,
    input  wire        joy_swap,
    output wire [11:0] joy_left,
    output wire [11:0] joy_right
);
    wire [39:0] mat;
    zx_keys zk (.keys(keys), .zx_mat(mat));
    wire [7:0] rsel = ~row;
    reg [4:0] pressed;
    integer r;
    always @* begin
        pressed = 5'd0;
        for (r = 0; r < 8; r = r + 1)
            if (rsel[r]) pressed = pressed | mat[5 * r +: 5];
    end
    assign col = ~pressed;

    wire shift = keys[15] | keys[52];
    wire crsr_d = keys[7], crsr_r = keys[2];
    assign ext[0]  = keys[61];                                  // C=
    assign ext[1]  = crsr_d & shift;                            // UP
    assign ext[2]  = keys[58];                                  // CTRL
    assign ext[3]  = keys[57];                                  // <-
    assign ext[4]  = keys[4];                                   // F1
    assign ext[5]  = keys[5];                                   // F3
    assign ext[6]  = keys[63];                                  // RUN/STOP
    assign ext[7]  = keys[51];                                  // HOME
    assign ext[8]  = keys[50] & ~shift;                         // ;
    assign ext[9]  = keys[59] & shift;                          // "
    assign ext[10] = keys[47] & ~shift;                         // ,
    assign ext[11] = keys[44] & ~shift;                         // .
    assign ext[12] = keys[0];                                   // DEL
    assign ext[13] = crsr_r & ~shift;                           // RIGHT
    assign ext[14] = crsr_r & shift;                            // LEFT
    assign ext[15] = crsr_d & ~shift;                           // DOWN

    wire [4:0] jl = joy_swap ? joy1 : joy2;                     // the C64's port 2 is the usual one: the Next's left stick
    wire [4:0] jr = joy_swap ? joy2 : joy1;
    // host order: 0 up, 1 down, 2 left, 3 right, 4 fire  ->  Next word: bit 0 R, 1 L, 2 D, 3 U, 4 B
    assign joy_left  = {7'd0, jl[4], jl[0], jl[1], jl[2], jl[3]};
    assign joy_right = {7'd0, jr[4], jr[0], jr[1], jr[2], jr[3]};
endmodule
